param([string]$ConnectionString,[string]$PublicUrl,[bool]$CookieSecure=$true,[bool]$TelegramEnabled=$false,[string]$TelegramToken='',[string]$TelegramChatId='',[bool]$WhatsAppEnabled=$false,[string]$WhatsAppNumber='',[string]$AdminEmails='')
. "$PSScriptRoot\_common.ps1"; $root=Get-RepoRoot; if(-not $ConnectionString){$ConnectionString=Read-Host 'Connection string PostgreSQL'}; if(-not $PublicUrl){$PublicUrl=Read-Host 'URL pública'}
if(-not (Select-String -Path (Join-Path $root '.gitignore') -Pattern 'appsettings\.Production\.json' -Quiet)){throw '.gitignore não ignora appsettings.Production.json'}
$obj=[ordered]@{App=@{Version='v4.4-WindowsIIS-Production-NoDocker';HostingMode='Windows/IIS';PublicUrl=$PublicUrl};ConnectionStrings=@{DefaultConnection=$ConnectionString};Authentication=@{CookieSecure=$CookieSecure};Telegram=@{Enabled=$TelegramEnabled;BotToken=$TelegramToken;AdminChatId=$TelegramChatId};WhatsApp=@{Enabled=$WhatsAppEnabled;Number=$WhatsAppNumber};Admin=@{AdminEmails=$AdminEmails}}
$obj|ConvertTo-Json -Depth 5|Set-Content (Join-Path $root 'src\HabitFlow.Web\appsettings.Production.json') -Encoding UTF8; Write-Check OK 'appsettings.Production.json local gerado (não versionar)'
